type Fund = { code:string; name:string; type:string; pinyin:string; fullPinyin:string };
type Point = { date:string; close:number };
type FundProfile = {classificationLabel?:string;benchmark?:string|null;strategy?:string|null;disclosedHoldings?:{code:string;name:string;weight:number;assetClass:string;market:string}[];holdingsAsOf?:string|null;manager?:string|null;managerSince?:string|null;fundScale?:number|null;managementFee?:number|null;custodyFee?:number|null;riskLevel?:string|null;notes?:string[]};
type Quote = { code:string; name:string; price:number|null; change:number|null; volume:number|null; amount:number|null; turnover?:number|null; time:string|null };
type Board = { code:string; name:string; change:number|null; price:number|null; amount:number|null };
