type BondQuote = {code:string;name:string;price:number|null;change:number|null;amount:number|null;volume:number|null;time:string|null;oneYearReturn:number|null;annualVolatility:number|null;maxDrawdown:number|null;historyPoints:number;source:string;error?:string};
