const fmt=(v:number|null|undefined,d=2)=>v==null||!Number.isFinite(v)?"—":v.toFixed(d);
const pct=(v:number|null|undefined)=>v==null||!Number.isFinite(v)?"—":(v>0?"+":"")+v.toFixed(2)+"%";
const money=(v:number)=>"¥"+v.toLocaleString("zh-CN",{maximumFractionDigits:2});
const cls=(v:number|null|undefined)=>v==null?"text-slate-400":v>=0?"text-rose-600":"text-emerald-600";
const groupType=(t:string)=>/货币/.test(t)?"货币基金":/债券/.test(t)?"债券基金":/QDII|海外/.test(t)?"QDII/海外":/FOF|养老/.test(t)?"FOF":/指数|ETF|联接/.test(t)?"指数/ETF":/商品/.test(t)?"商品基金":/股票/.test(t)?"股票基金":/混合/.test(t)?"混合基金":"其他/待识别";
function calc(points:Point[]){
 if(points.length<3)return null;
 const sorted=[...points].sort((a,b)=>a.date.localeCompare(b.date));
 const first=sorted[0],last=sorted.at(-1)!;
 const rets=sorted.slice(1).map((p,i)=>p.close/sorted[i].close-1).filter(Number.isFinite);
 const mean=rets.reduce((a,b)=>a+b,0)/rets.length;
 const variance=rets.reduce((a,b)=>a+(b-mean)**2,0)/Math.max(1,rets.length-1);
 const vol=Math.sqrt(variance*252)*100;
 let peak=sorted[0].close,maxDD=0,ulcer=0,under=0,daysUnder=0,maxRecovery=0;
 for(const p of sorted){peak=Math.max(peak,p.close);const dd=(p.close/peak-1)*100;maxDD=Math.min(maxDD,dd);ulcer+=dd*dd;if(dd<0){under++;daysUnder++;}else{maxRecovery=Math.max(maxRecovery,daysUnder);daysUnder=0;}}
 const elapsed=Math.max(1,(new Date(last.date+"T00:00:00").getTime()-new Date(first.date+"T00:00:00").getTime())/86400000);
 const total=(last.close/first.close-1)*100;
 const annual=(Math.pow(last.close/first.close,365/elapsed)-1)*100;
 const rf=Math.pow(1.02,1/252)-1;
 const sharpe=variance>0?(mean-rf)/Math.sqrt(variance)*Math.sqrt(252):null;
 const downside=rets.filter(x=>x<0);
 const downDev=downside.length?Math.sqrt(downside.reduce((s,x)=>s+x*x,0)/downside.length*252)*100:null;
 const sortino=downDev&&downDev>0?(annual-2)/downDev:null;
 const calmar=maxDD<0?annual/Math.abs(maxDD):null;
 const upi=ulcer>0?annual/Math.sqrt(ulcer/sorted.length):null;
 return {total,annual,vol,maxDD,sharpe,sortino,calmar,upi,ulcer:Math.sqrt(ulcer/sorted.length),observations:sorted.length,start:first.date,end:last.date,downside:downDev,positiveDays:rets.filter(x=>x>0).length,winRate:rets.length?rets.filter(x=>x>0).length/rets.length*100:0,maxRecovery};
}
function Card({title,sub,children}:{title:string;sub?:string;children:ReactNode}){return <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="mb-4"><h2 className="text-sm font-bold text-slate-800">{title}</h2>{sub&&<p className="mt-1 text-xs leading-5 text-slate-400">{sub}</p>}</div>{children}</section>}
function Stat({label,value,note}:{label:string;value:string;note?:string}){return <div className="rounded-xl border border-slate-100 bg-slate-50 p-4"><p className="text-[11px] text-slate-500">{label}</p><p className="mt-2 text-xl font-bold tabular-nums text-slate-800">{value}</p>{note&&<p className="mt-1 text-[10px] text-slate-400">{note}</p>}</div>}
function Table({heads,children}:{heads:string[];children:React.ReactNode}){return <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-xs"><thead><tr className="border-b border-slate-100 text-[10px] text-slate-400">{heads.map(h=><th key={h} className="px-3 py-3 font-medium">{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}
function Line({points}:{points:Point[]}){if(points.length<2)return <div className="grid h-56 place-items-center text-sm text-slate-400">暂无足够历史净值</div>;const vals=points.map(p=>p.close);const lo=Math.min(...vals),hi=Math.max(...vals);const path=points.map((p,i)=>`${i?"L":"M"}${i/(points.length-1)*760} ${190-(p.close-lo)/(hi-lo||1)*160}`).join(" ");return <div><svg viewBox="0 0 760 210" className="h-56 w-full" preserveAspectRatio="none"><path d={path} fill="none" stroke="#0891b2" strokeWidth="2.5" vectorEffect="non-scaling-stroke"/><path d={path+" L760 210 L0 210 Z"} fill="#06b6d4" opacity=".08"/></svg><div className="flex justify-between text-[10px] text-slate-400"><span>{points[0].date}</span><span>{points.at(-1)?.date}</span></div></div>}
